import base64
import hashlib
import os
import json
from PIL import Image

def decode(name, n, sha, b64):
    # Strip any whitespace and add padding if needed
    b64 = b64.strip()
    # Add padding if necessary
    missing_padding = len(b64) % 4
    if missing_padding:
        b64 += '=' * (4 - missing_padding)
    raw = base64.b64decode(b64)
    assert len(raw) == n, (name, len(raw), n)
    assert hashlib.sha256(raw).hexdigest() == sha, name
    path = f'/tmp/{name}'
    open(path,'wb').write(raw)
    return path

def stitch_rows(row_paths, out_path, expect_w, expect_h):
    parts = [Image.open(p).convert('RGBA') for p in row_paths]
    w = parts[0].size[0]
    assert all(p.size == (w, 64) for p in parts), [p.size for p in parts]
    out = Image.new('RGBA', (w, 64 * 4))
    for i, p in enumerate(parts):
        out.paste(p, (0, i * 64))
    assert out.size == (expect_w, expect_h), out.size
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    out.save(out_path, 'PNG')
    print(f"{out_path} -> {out.size}, {os.path.getsize(out_path)} bytes")

