# Decode all files
print("=== Decoding slime1 row files ===")
decoded = {}
for name, data in FILES.items():
    try:
        print(f"Decoding {name}...")
        path = decode(name, data['n'], data['sha256'], data['b64'])
        decoded[name] = path
        print(f"  ✓ {name}")
    except AssertionError as e:
        print(f"  ✗ FAILED: {name} - {e}")
        print(f"     Cannot continue with {name}")
        # Don't exit - continue with what we have
        
# Build idle sheet if we have all 4 rows
idle_rows = ['slime1-idle-r0.png', 'slime1-idle-r1.png', 'slime1-idle-r2.png', 'slime1-idle-r3.png']
